+    state.projectiles.push({
+      kind: 'pulse', x: ox, y: oy, px: ox, py: oy,
+      target, tx: target.x, ty: target.y,
+      speed: 840, dmg: lv.dmg, color: def.color, tower, life: 2,
+    });
+    sound.play('shoot');
+  } else if (tower.type === 'cannon') {
+    const dist = Math.hypot(target.x - ox, target.y - oy);
+    state.projectiles.push({
+      kind: 'shell', sx: ox, sy: oy, x: ox, y: oy, px: ox, py: oy,
+      tx: target.x, ty: target.y, t: 0, dur: Math.max(0.3, Math.min(0.95, dist / 540)),
+      h: 46, dmg: lv.dmg, splash: lv.splash, color: def.color, tower,
+    });
+    sound.play('cannon');
+  } else if (tower.type === 'cryo') {
+    state.projectiles.push({
+      kind: 'frost', x: ox, y: oy, px: ox, py: oy,
+      target, tx: target.x, ty: target.y,
+      speed: 660, dmg: lv.dmg, splash: lv.splash,
+      slow: lv.slow, slowDur: lv.slowDur, color: def.color, tower, life: 2.2,
+    });
+    sound.play('frost');
+  } else if (tower.type === 'arc') {
+    const hit = [target];
+    let cur = target;
+    for (let i = 1; i < lv.chains; i++) {
+      let next = null;
+      let bestD = Infinity;
+      for (const e of state.enemies) {
+        if (e.dead || hit.includes(e)) continue;
+        const d = Math.hypot(e.x - cur.x, e.y - cur.y);
+        if (d < lv.chainRange && d < bestD) { bestD = d; next = e; }
+      }
+      if (!next) break;
+      hit.push(next);
+      cur = next;
+    }
+    const points = [{ x: ox, y: oy }];
+    let dmg = lv.dmg;
+    hit.forEach((e, i) => {
+      points.push({ x: e.x, y: e.y });
+      damage(e, dmg, { tower, text: i === 0, color: '#dcd2ff' });
+      dmg *= 0.85;
+    });
+    state.beams.push({ points, life: 0.24, maxLife: 0.24, color: '#b9a6ff', width: 1.7 });
+    sound.play('arc');
+    tower.flash = 1;
+  } else if (tower.type === 'rail') {
+    const end = {
+      x: ox + Math.cos(tower.angle) * lv.range,
+      y: oy + Math.sin(tower.angle) * lv.range,
+    };
+    for (const e of state.enemies) {
+      if (e.dead) continue;
+      if (segmentHit(ox, oy, end.x, end.y, e.x, e.y, e.radius + 7)) {
+        damage(e, lv.dmg, { tower, text: true, color: '#ffd2ec' });
+      }
+    }
+    state.beams.push({
+      points: [{ x: ox, y: oy }, end],
+      life: 0.32, maxLife: 0.32, color: '#ff8ad4', width: 3.4,
+    });
+    state.shake = Math.max(state.shake, 3);
+    sound.play('rail');
+    tower.flash = 1;
+  }
+}
+
+function updateTowers(dt) {
+  for (const tower of state.towers) {
+    const def = C.TOWERS[tower.type];
+    const lv = def.levels[tower.level];
+    if (tower.flash > 0) tower.flash = Math.max(0, tower.flash - dt * 8);
+    if (tower.cooldown > 0) tower.cooldown -= dt;
+    if (!state.waveActive) {
+      tower.angle = -Math.PI / 2 + Math.sin(state.renderTime * 0.6 + tower.seed) * 0.5;
+      continue;
+    }
+    const target = findTarget(tower, lv.range);
+    if (target) {
+      const desired = Math.atan2(target.y - (tower.y - 5), target.x - tower.x);
+      tower.angle = lerpAngle(tower.angle, desired, Math.min(1, dt * 14));
+      if (tower.cooldown <= 0) {
+        fire(tower, def, lv, target);
+        tower.cooldown = 1 / lv.rate;
+      }
+    }
+  }
+}
+
+function updateProjectiles(dt) {
+  for (const p of state.projectiles) {
+    if (p.dead) continue;
+    p.px = p.x;
+    p.py = p.y;
+    if (p.kind === 'pulse') {
+      if (p.target && !p.target.dead) {
+        p.tx = p.target.x;
+        p.ty = p.target.y;
+      }
+      const dx = p.tx - p.x;
+      const dy = p.ty - p.y;
+      const d = Math.hypot(dx, dy);
+      const step = p.speed * dt;
+      if (d <= step + 7) {
+        p.x = p.tx;
+        p.y = p.ty;
+        p.dead = true;
+        if (p.target && !p.target.dead) {
+          damage(p.target, p.dmg, { tower: p.tower });
+          burst(p.x, p.y, 3, p.color, 50, 0.25);
+        }
+      } else {
+        p.x += (dx / d) * step;
+        p.y += (dy / d) * step;
+      }
+      p.life -= dt;
+      if (p.life <= 0) p.dead = true;
+    } else if (p.kind === 'shell') {
+      p.t += dt / p.dur;
+      if (p.t >= 1) {
+        p.t = 1;
+        p.x = p.tx;
+        p.y = p.ty;
+        p.dead = true;
+        for (const e of state.enemies) {
+          if (e.dead) continue;
+          const d = Math.hypot(e.x - p.tx, e.y - p.ty);
+          if (d <= p.splash + e.radius * 0.5) {
+            const falloff = 1 - (d / p.splash) * 0.45;
+            damage(e, p.dmg * falloff, { tower: p.tower });
+          }
+        }
+        explosion(p.tx, p.ty, p.color, 1.05);
+      } else {
+        p.x = p.sx + (p.tx - p.sx) * p.t;
+        p.y = p.sy + (p.ty - p.sy) * p.t;
+      }
+    } else if (p.kind === 'frost') {
+      if (p.target && !p.target.dead) {
+        p.tx = p.target.x;
+        p.ty = p.target.y;
+      }
+      const dx = p.tx - p.x;
+      const dy = p.ty - p.y;
+      const d = Math.hypot(dx, dy);
+      const step = p.speed * dt;
+      if (d <= step + 7) {
+        p.x = p.tx;
+        p.y = p.ty;
+        p.dead = true;
+        for (const e of state.enemies) {
+          if (e.dead) continue;
+          if (Math.hypot(e.x - p.x, e.y - p.y) <= p.splash + e.radius * 0.4) {
+            damage(e, p.dmg, { tower: p.tower });
+            const resist = e.def.slowResist || 0;
+            e.slowTimer = Math.max(e.slowTimer, p.slowDur);
+            e.slowAmount = Math.max(e.slowAmount, p.slow * (1 - resist));
+          }
+        }
+        ring(p.x, p.y, p.splash + 6, '#a9e6ff', 0.4);
+        burst(p.x, p.y, 8, '#cdf3ff', 70, 0.35);
+      } else {
+        p.x += (dx / d) * step;
+        p.y += (dy / d) * step;
+      }
+      p.life -= dt;
+      if (p.life <= 0) p.dead = true;
+    }
+  }
+  state.projectiles = state.projectiles.filter((p) => !p.dead);
+}
+
+function updateEffects(dt) {
+  for (const p of state.particles) {
+    p.life -= dt;
+    if (p.life <= 0) continue;
+    p.x += p.vx * dt;
+    p.y += p.vy * dt;
+    p.vx *= Math.max(0, 1 - p.drag * dt);
+    p.vy *= Math.max(0, 1 - p.drag * dt);
+    p.vy += (p.gravity || 0) * dt;
+  }
+  state.particles = state.particles.filter((p) => p.life > 0);
+
+  for (const t of state.texts) {
+    t.life -= dt;
+    t.y += t.vy * dt;
+  }
+  state.texts = state.texts.filter((t) => t.life > 0);
+
+  for (const s of state.shocks) {
+    s.life -= dt;
+    s.r += (s.maxR - s.r) * Math.min(1, dt * 9);
+  }
+  state.shocks = state.shocks.filter((s) => s.life > 0);
+
+  for (const b of state.beams) b.life -= dt;
+  state.beams = state.beams.filter((b) => b.life > 0);
+
+  updateDust(dt);
+}
+
+// ---- main simulation ----
+
+function simulate(dt) {
+  state.time += dt;
+  state.shake = Math.max(0, state.shake - dt * 34);
+  state.flash = Math.max(0, state.flash - dt * 2.4);
+  state.corePulse = Math.max(0, state.corePulse - dt * 1.8);
+  state.portalPulse = Math.max(0, state.portalPulse - dt * 3);
+
+  updateEffects(dt);
+  updateProjectiles(dt);
+
+  if (state.waveActive) {
+    state.waveTime += dt;
+    while (state.spawnQueue.length && state.spawnQueue[0].at <= state.waveTime) {
+      const next = state.spawnQueue.shift();
+      spawnEnemy(next.type);
+      state.waveSpawned++;
+    }
+    updateEnemies(dt);
+    if (state.mode !== 'playing') return;
+    updateTowers(dt);
+    if (state.mode !== 'playing') return;
+    state.enemies = state.enemies.filter((e) => !e.dead);
+    if (state.spawnQueue.length === 0 && state.enemies.length === 0) {
+      completeWave();
+    }
+  } else {
+    state.prep -= dt;
+    if (state.prep <= 0) {
+      startWave(false);
+    } else {
+      updateTowers(dt);
+    }
+  }
+}
+
 buildCards();
 bindEvents();
 makeDust();
 updateBest();

input.content:
:root {
  --bg: #05080f;
  --panel: rgba(10, 18, 32, 0.92);
  --line: rgba(120, 200, 255, 0.14);
  --cyan: #4de8ff;
  --magenta: #ff4d9d;
  --gold: #ffd166;
  --green: #6ef7a5;
  --red: #ff5b6e;
  --text: #e8f4ff;
  --muted: #8fa6c4;
  --font: "Segoe UI", "Inter", system-ui, -apple-system, sans-serif;
  --mono: ui-monospace, "SF Mono", "Cascadia Code", Menlo, monospace;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  background: var(--bg);
}

body {
  font-family: var(--font);
  color: var(--text);
  overflow: hidden;
  overscroll-behavior: none;
  background:
    radial-gradient(1200px 700px at 15% 0%, rgba(30, 90, 160, 0.18), transparent 60%),
    radial-gradient(1000px 600px at 85% 100%, rgba(180, 40, 120, 0.12), transparent 60%),
    var(--bg);
  -webkit-tap-highlight-color: transparent;
}

button { font-family: inherit; }

#app {
  height: 100dvh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* ---------------- HUD ---------------- */

.hud {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  gap: 16px;
  padding: calc(8px + env(safe-area-inset-top)) 18px 8px;
  background: linear-gradient(180deg, rgba(8, 14, 26, 0.95), rgba(8, 14, 26, 0.62));
  border-bottom: 1px solid var(--line);
  backdrop-filter: blur(14px);
  z-index: 20;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

.brand-mark {
  width: 30px;
  height: 30px;
  flex: 0 0 auto;
  background: linear-gradient(140deg, var(--cyan), #7b7bff 55%, var(--magenta));
  clip-path: polygon(50% 0%, 93% 25%, 93% 75%, 50% 100%, 7% 75%, 7% 25%);
  filter: drop-shadow(0 0 10px rgba(77, 232, 255, 0.55));
}

.brand-text {
  display: flex;
  flex-direction: column;
  font-size: 8px;
  letter-spacing: 0.34em;
  color: var(--muted);
  line-height: 1.2;
}

.brand-text strong {
  font-size: 14px;
  letter-spacing: 0.2em;
  color: #f2fbff;
}

.stats {
  display: flex;
  align-items: center;
  gap: 4px;
  margin: 0 auto;
}

.stat {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 12px 5px 8px;
  border-radius: 11px;
  border: 1px solid rgba(255, 255, 255, 0.04);
  background: rgba(255, 255, 255, 0.022);
}

.stat-ico {
  width: 27px;
  height: 27px;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.04);
}

.stat-ico svg { width: 15px; height: 15px; fill: currentColor; }
.stat-ico.heart { color: #ff7a9c; background: rgba(255, 90, 130, 0.1); }
.stat-ico.gold { color: var(--gold); background: rgba(255, 209, 102, 0.1); }
.stat-ico.gold .inner { fill: rgba(0, 0, 0, 0.35); }
.stat-ico.wave { color: var(--cyan); background: rgba(77, 232, 255, 0.1); }
.stat-ico.wave svg { fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; }

.stat-body {
  display: flex;
  flex-direction: column;
  line-height: 1.1;
}

.stat-body b {
  font-family: var(--mono);
  font-size: 15px;
  font-weight: 700;
  color: #f4fbff;
}

.stat-body i {
  font-style: normal;
  font-size: 7px;
  letter-spacing: 0.2em;
  color: var(--muted);
  margin-top: 2px;
}

.score-stat { padding-left: 14px; }
.score-stat b { color: #cfe6ff; }

.actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.icon-btn {
  width: 36px;
  height: 36px;
  border-radius: 10px;
  border: 1px solid rgba(140, 200, 255, 0.16);
  background: rgba(255, 255, 255, 0.03);
  color: #cfe6ff;
  font-size: 15px;
  font-weight: 700;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: border-color 0.2s, background 0.2s, transform 0.15s;
}

.icon-btn svg { width: 15px; height: 15px; fill: currentColor; }
.icon-btn.speed { width: auto; padding: 0 10px; font-family: var(--mono); font-size: 12px; }
.icon-btn:hover { border-color: rgba(77, 232, 255, 0.55); background: rgba(77, 232, 255, 0.08); }
.icon-btn:active { transform: scale(0.95); }
.icon-btn.muted { color: var(--red); border-color: rgba(255, 91, 110, 0.4); }

/* ---------------- Stage ---------------- */

.stage {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 10px 0 6px;
}

#game {
  display: block;
  border-radius: 16px;
  background: #060b15;
  box-shadow:
    0 0 0 1px rgba(120, 200, 255, 0.16),
    0 30px 70px -30px rgba(0, 0, 0, 0.95),
    0 0 90px -40px rgba(77, 232, 255, 0.5);
  touch-action: none;
  user-select: none;
  cursor: crosshair;
}

/* ---------------- Toasts / banner / hint ---------------- */

.toasts {
  position: absolute;
  top: 14px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  z-index: 9;
  pointer-events: none;
  max-width: 86%;
}

.toast {
  padding: 8px 15px;
  border-radius: 8px;
  background: rgba(9, 16, 29, 0.92);
  border: 1px solid rgba(120, 200, 255, 0.16);
  border-left: 3px solid var(--cyan);
  color: #dff4ff;
  font-size: 11px;
  letter-spacing: 0.06em;
  box-shadow: 0 10px 30px -12px #000;
  backdrop-filter: blur(10px);
  animation: toastIn 0.28s ease both;
  white-space: nowrap;
}

.toast.gold { border-left-color: var(--gold); color: #ffe6a8; }
.toast.danger { border-left-color: var(--red); color: #ffc2ca; }
.toast.good { border-left-color: var(--green); color: #c8ffdf; }
.toast.out { animation: toastOut 0.25s ease forwards; }

@keyframes toastIn {
  from { opacity: 0; transform: translateY(-8px) scale(0.96); }
  to { opacity: 1; transform: none; }
}
@keyframes toastOut {
  to { opacity: 0; transform: translateY(-6px); }
}

.wave-banner {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  font-size: clamp(34px, 7vw, 76px);
  font-weight: 900;
  letter-spacing: 0.18em;
  color: #f4fdff;
  text-shadow: 0 0 26px rgba(77, 232, 255, 0.85), 0 0 80px rgba(77, 232, 255, 0.4);
  pointer-events: none;
  opacity: 0;
  z-index: 8;
}

.wave-banner.show { animation: bannerPop 1.8s ease forwards; }

@keyframes bannerPop {
  0% { opacity: 0; transform: scale(0.82); letter-spacing: 0.32em; }
  16% { opacity: 1; transform: scale(1); }
  70% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.08); }
}

.hint {
  position: absolute;
  bottom: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 17px;
  border-radius: 999px;
  background: rgba(9, 16, 29, 0.92);
  border: 1px solid rgba(77, 232, 255, 0.32);
  font-size: 10px;
  letter-spacing: 0.12em;
  color: #dff6ff;
  white-space: nowrap;
  z-index: 7;
  backdrop-filter: blur(10px);
  box-shadow: 0 10px 30px -14px #000;
}

.hint b { color: var(--cyan); }
.hint span { color: var(--muted); letter-spacing: 0.06em; }
.hint.poor { border-color: rgba(255, 91, 110, 0.5); }
.hint.poor b { color: var(--red); }

/* ---------------- Wave button ---------------- */

.wave-btn {
  position: absolute;
  right: 24px;
  bottom: 20px;
  width: 116px;
  height: 116px;
  border-radius: 50%;
  border: none;
  background: radial-gradient(circle at 50% 34%, rgba(27, 58, 88, 0.96), rgba(7, 14, 27, 0.98));
  color: #e8f9ff;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  z-index: 7;
  box-shadow:
    0 0 0 1px rgba(77, 232, 255, 0.24),
    0 14px 34px -12px rgba(0, 0, 0, 0.9),
    inset 0 0 26px rgba(77, 232, 255, 0.07);
  transition: transform 0.16s, box-shadow 0.25s;
}

.wave-btn:hover { transform: scale(1.045); box-shadow: 0 0 0 1px rgba(77, 232, 255, 0.55), 0 16px 38px -12px rgba(0, 0, 0, 0.9), 0 0 36px -10px rgba(77, 232, 255, 0.5); }
.wave-btn:active { transform: scale(0.98); }
.wave-btn:disabled { cursor: default; transform: none; }

.wave-ring {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
  overflow: visible;
}

.ring-bg {
  fill: none;
  stroke: rgba(120, 180, 255, 0.12);
  stroke-width: 3;
}

.ring-fill {
  fill: none;
  stroke: var(--cyan);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 276.46;
  stroke-dashoffset: 0;
  filter: drop-shadow(0 0 6px rgba(77, 232, 255, 0.8));
  transition: stroke-dashoffset 0.2s linear, stroke 0.2s;
}

.wave-title {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.15em;
  line-height: 1.3;
  max-width: 82px;
  text-align: center;
  color: #dff8ff;
}

.wave-sub {
  font-family: var(--mono);
  font-size: 11px;
  color: var(--cyan);
  letter-spacing: 0.02em;
}

.wave-btn.active { cursor: default; }
.wave-btn.active .ring-fill { stroke: var(--magenta); filter: drop-shadow(0 0 7px rgba(255, 77, 157, 0.8)); }
.wave-btn.active .wave-sub { color: #ffa9c9; }
.wave-btn.active::after {
  content: "";
  position: absolute;
  inset: 10px;
  border-radius: 50%;
  border: 1px solid rgba(255, 77, 157, 0.2);
  animation: wavePulse 1.6s ease-out infinite;
}

@keyframes wavePulse {
  0% { transform: scale(0.92); opacity: 0.8; }
  100% { transform: scale(1.12); opacity: 0; }
}

/* ---------------- Tower panel ---------------- */

.tower-panel {
  position: absolute;
  left: 24px;
  bottom: 20px;
  width: 302px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid rgba(120, 200, 255, 0.18);
  border-left: 3px solid var(--tower-color, var(--cyan));
  background: rgba(9, 16, 29, 0.94);
  backdrop-filter: blur(14px);
  box-shadow: 0 20px 50px -20px #000;
  z-index: 8;
  animation: panelIn 0.18s ease both;
}

@keyframes panelIn {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}

.tp-head { display: flex; align-items: center; gap: 9px; }

.tp-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--tower-color, var(--cyan));
  box-shadow: 0 0 10px var(--tower-color, var(--cyan));
}

.tp-id { display: flex; flex-direction: column; line-height: 1.15; }

.tp-name {
  font-size: 13px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #f0fbff;
}

.tp-level {
  font-family: var(--mono);
  font-size: 8px;
  letter-spacing: 0.22em;
  color: var(--muted);
  margin-top: 2px;
}

.tp-close {
  margin-left: auto;
  width: 26px;
  height: 26px;
  border-radius: 7px;
  border: none;
  background: transparent;
  color: var(--muted);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
}

.tp-close:hover { background: rgba(255, 255, 255, 0.06); color: #fff; }

.tp-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 5px;
  margin: 10px 0 8px;
}

.tp-stats div {
  background: rgba(255, 255, 255, 0.028);
  border-radius: 8px;
  padding: 6px 2px 5px;
  text-align: center;
}

.tp-stats span {
  display: block;
  font-size: 7px;
  letter-spacing: 0.16em;
  color: var(--muted);
  margin-bottom: 2px;
}

.tp-stats b {
  font-family: var(--mono);
  font-size: 12px;
  color: #f1fbff;
}

.tp-meta {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  font-size: 8px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--muted);
  margin-bottom: 10px;
}

.tp-meta b { color: #d8ecff; font-family: var(--mono); }

.tp-actions { display: flex; gap: 7px; }

.tp-upgrade {
  flex: 1;
  padding: 9px 6px;
  border-radius: 8px;
  border: 1px solid rgba(77, 232, 255, 0.42);
  background: linear-gradient(135deg, rgba(77, 232, 255, 0.18), rgba(77, 232, 255, 0.05));
  color: #ccf7ff;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.1em;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s;
}

.tp-upgrade:hover:not(:disabled) { background: rgba(77, 232, 255, 0.26); border-color: var(--cyan); }
.tp-upgrade:disabled { opacity: 0.38; cursor: not-allowed; }

.tp-sell {
  padding: 9px 11px;
  border-radius: 8px;
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.035);
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.08em;
  cursor: pointer;
}

.tp-sell:hover { color: #fff; border-color: rgba(255, 209, 102, 0.5); }

/* ---------------- Dock ---------------- */

.dock {
  flex: 0 0 auto;
  display: flex;
  justify-content: center;
  padding: 7px 16px calc(9px + env(safe-area-inset-bottom));
  background: linear-gradient(180deg, rgba(8, 14, 26, 0.5), rgba(8, 14, 26, 0.95));
  border-top: 1px solid var(--line);
  backdrop-filter: blur(12px);
  z-index: 20;
}

.dock-inner {
  display: flex;
  align-items: stretch;
  gap: 8px;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  padding: 2px;
  scrollbar-width: none;
}

.dock-inner::-webkit-scrollbar { display: none; }

.tcard {
  position: relative;
  flex: 0 0 auto;
  width: 102px;
  padding: 7px 6px 6px;
  border-radius: 12px;
  border: 1px solid rgba(120, 200, 255, 0.12);
  background: linear-gradient(180deg, rgba(20, 32, 52, 0.62), rgba(9, 16, 29, 0.86));
  color: var(--text);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  cursor: pointer;
  transition: transform 0.15s, border-color 0.2s, box-shadow 0.2s, background 0.2s;
}

.tcard:hover {
  transform: translateY(-2px);
  border-color: rgba(77, 232, 255, 0.4);
  background: linear-gradient(180deg, rgba(26, 44, 68, 0.7), rgba(9, 16, 29, 0.9));
}

.tcard.selected {
  border-color: var(--cyan);
  background: linear-gradient(180deg, rgba(24, 62, 88, 0.85), rgba(10, 20, 36, 0.92));
  box-shadow: 0 0 0 1px var(--cyan), 0 10px 24px -12px rgba(77, 232, 255, 0.8);
}

.tcard.poor { opacity: 0.42; }
.tcard.poor .tcost { color: var(--red); }

.tkey {
  position: absolute;
  top: 4px;
  left: 5px;
  width: 13px;
  height: 13px;
  display: grid;
  place-items: center;
  border-radius: 4px;
  border: 1px solid rgba(255, 255, 255, 0.14);
  font-family: var(--mono);
  font-size: 7px;
  color: var(--muted);
}

.ticon { width: 44px; height: 44px; display: block; }

.tname {
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #dff4ff;
}

.tcost {
  display: flex;
  align-items: center;
  gap: 3px;
  font-family: var(--mono);
  font-size: 10px;
  color: var(--gold);
}

.tcost i { font-style: normal; font-size: 7px; }

/* ---------------- Overlays ---------------- */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  padding: 20px;
  overflow-y: auto;
  background: rgba(3, 6, 12, 0.72);
  backdrop-filter: blur(10px);
  animation: fadeIn 0.25s ease both;
}

.overlay[hidden] { display: none !important; }

@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }

.title-overlay {
  z-index: 60;
  background:
    radial-gradient(circle at 50% 38%, rgba(10, 26, 48, 0.35), rgba(3, 6, 12, 0.86));
  backdrop-filter: blur(6px);
}

.title-card {
  width: min(620px, 100%);
  text-align: center;
  padding: 20px;
  animation: riseIn 0.55s cubic-bezier(0.2, 0.9, 0.2, 1) both;
}

@keyframes riseIn {
  from { opacity: 0; transform: translateY(18px); }
  to { opacity: 1; transform: none; }
}

.kicker {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.42em;
  color: var(--cyan);
  text-transform: uppercase;
  margin-bottom: 14px;
}

.title-card h1 {
  margin: 0;
  font-size: clamp(58px, 12vw, 112px);
  line-height: 0.84;
  font-weight: 900;
  letter-spacing: 0.01em;
  color: #f4fcff;
  text-shadow: 0 0 46px rgba(77, 232, 255, 0.4), 0 10px 50px rgba(0, 0, 0, 0.8);
}

.title-card h1 span {
  background: linear-gradient(100deg, #4de8ff 10%, #8f7bff 50%, #ff4d9d 90%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 0 22px rgba(143, 123, 255, 0.35));
}

.tagline {
  max-width: 440px;
  margin: 20px auto 18px;
  color: #a9c0dc;
  font-size: 13px;
  line-height: 1.65;
}

.title-badges {
  display: flex;
  justify-content: center;
  gap: 26px;
  color: var(--muted);
  font-size: 8px;
  letter-spacing: 0.2em;
}

.title-badges span { display: flex; flex-direction: column; gap: 3px; }
.title-badges b { font-family: var(--mono); font-size: 17px; color: #dff4ff; letter-spacing: 0; }

.title-actions,
.modal-actions {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 26px;
}

.primary {
  border: none;
  padding: 14px 34px;
  border-radius: 12px;
  background: linear-gradient(135deg, #6df2ff, #33b6ff);
  color: #03131d;
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.16em;
  cursor: pointer;
  box-shadow: 0 0 32px rgba(77, 232, 255, 0.35), inset 0 1px 0 rgba(255, 255, 255, 0.55);
  transition: transform 0.15s, box-shadow 0.2s;
}

.primary:hover { transform: translateY(-2px); box-shadow: 0 0 44px rgba(77, 232, 255, 0.55), inset 0 1px 0 rgba(255, 255, 255, 0.6); }
.primary:active { transform: translateY(0); }

.ghost {
  padding: 14px 24px;
  border-radius: 12px;
  border: 1px solid rgba(140, 210, 255, 0.26);
  background: rgba(255, 255, 255, 0.03);
  color: #cfe8ff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.16em;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}

.ghost:hover { border-color: var(--cyan); background: rgba(77, 232, 255, 0.07); }

.best-line {
  margin-top: 22px;
  font-size: 8px;
  letter-spacing: 0.3em;
  color: var(--muted);
}

.best-line b {
  font-family: var(--mono);
  font-size: 13px;
  color: var(--gold);
  margin-left: 6px;
  letter-spacing: 0;
}

.modal {
  width: min(540px, 100%);
  padding: 30px;
  text-align: center;
  border-radius: 20px;
  border: 1px solid rgba(120, 200, 255, 0.18);
  background: linear-gradient(180deg, rgba(16, 26, 44, 0.97), rgba(7, 13, 24, 0.98));
  box-shadow: 0 40px 90px -30px #000, 0 0 70px -40px rgba(77, 232, 255, 0.5);
  animation: riseIn 0.3s ease both;
}

.modal.small { width: min(420px, 100%); }

.modal h2 {
  margin: 0 0 8px;
  font-size: clamp(32px, 6vw, 48px);
  font-weight: 900;
  letter-spacing: 0.08em;
  color: #f6fdff;
  text-shadow: 0 0 30px rgba(77, 232, 255, 0.3);
}

.modal p { margin: 0; color: var(--muted); font-size: 12px; line-height: 1.6; }

.end-modal .kicker { color: #ff9db3; }
#endTitle { color: #fff; }

.end-stats {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 7px;
  margin: 22px 0 2px;
}

.end-stats div {
  padding: 10px 4px;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(120, 200, 255, 0.08);
}

.end-stats span {
  display: block;
  font-size: 7px;
  letter-spacing: 0.2em;
  color: var(--muted);
  margin-bottom: 4px;
}

.end-stats b { font-family: var(--mono); font-size: 17px; color: #f2fbff; }

.help-modal { width: min(600px, 100%); text-align: left; }
.help-modal h2 { text-align: center; }
.help-modal > .kicker { text-align: center; }

.help-grid { display: grid; gap: 9px; margin: 20px 0 16px; }

.help-step {
  display: flex;
  gap: 12px;
  padding: 11px 13px;
  border-radius: 11px;
  border: 1px solid rgba(120, 200, 255, 0.1);
  background: rgba(255, 255, 255, 0.022);
}

.help-step > b {
  font-family: var(--mono);
  font-size: 15px;
  color: var(--cyan);
  min-width: 24px;
}

.help-step strong {
  display: block;
  font-size: 10px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #dff4ff;
}

.help-step p { margin: 3px 0 0; font-size: 11px; line-height: 1.5; }

.help-keys {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 6px 16px;
  font-size: 9px;
  letter-spacing: 0.08em;
  color: var(--muted);
}

kbd {
  display: inline-block;
  min-width: 18px;
  padding: 2px 5px;
  border-radius: 5px;
  border: 1px solid rgba(140, 200, 255, 0.22);
  border-bottom-width: 2px;
  background: rgba(255, 255, 255, 0.05);
  font-family: var(--mono);
  font-size: 9px;
  color: #dff4ff;
  text-align: center;
}

/* ---------------- Menu state ---------------- */

body[data-mode="menu"] .wave-btn,
body[data-mode="menu"] .tower-panel,
body[data-mode="menu"] .hint { display: none; }

body[data-mode="menu"] .dock { opacity: 0.4; }
body[data-mode="menu"] .stage { filter: saturate(0.9); }

/* ---------------- Responsive ---------------- */

@media (max-width: 900px) {
  .hud { gap: 10px; padding-left: 12px; padding-right: 12px; }
  .brand-text { display: none; }
  .stat { padding: 4px 8px 4px 6px; gap: 6px; }
  .stat-ico { width: 24px; height: 24px; }
  .stat-body b { font-size: 14px; }
  .score-stat { display: none; }
  .tower-panel { width: 284px; }
}

@media (max-width: 760px) {
  .hud {
    padding: calc(6px + env(safe-area-inset-top)) 9px 6px;
    gap: 8px;
  }
  .brand-mark { width: 24px; height: 24px; }
  .stats { gap: 3px; }
  .stat { padding: 3px 6px 3px 5px; border-radius: 9px; }
  .stat-ico { width: 21px; height: 21px; border-radius: 6px; }
  .stat-ico svg { width: 12px; height: 12px; }
  .stat-body b { font-size: 12px; }
  .stat-body i { display: none; }
  .actions { gap: 4px; }
  .icon-btn { width: 32px; height: 32px; border-radius: 9px; font-size: 13px; }
  .icon-btn svg { width: 13px; height: 13px; }
  .icon-btn.speed { padding: 0 7px; font-size: 10px; }

  .stage { padding: 4px 0 0; }
  #game { border-radius: 10px; }

  .wave-btn { right: 10px; bottom: 10px; width: 88px; height: 88px; }
  .wave-title { font-size: 7.5px; max-width: 64px; letter-spacing: 0.1em; }
  .wave-sub { font-size: 9px; }

  .tower-panel {
    left: 8px;
    right: 8px;
    bottom: 8px;
    width: auto;
    padding: 9px 10px;
  }
  .tp-stats b { font-size: 11px; }
  .tp-name { font-size: 12px; }
  .tp-meta { margin-bottom: 7px; }
  .tp-upgrade, .tp-sell { padding: 8px 4px; }

  .stage:has(.tower-panel:not([hidden])) .wave-btn {
    opacity: 0;
    pointer-events: none;
    transform: scale(0.8);
  }

  .hint {
    top: 8px;
    bottom: auto;
    left: 8px;
    right: 8px;
    transform: none;
    justify-content: center;
    white-space: normal;
    text-align: center;
    font-size: 8.5px;
    padding: 7px 10px;
    max-width: calc(100% - 16px);
  }

  .toasts { top: 48px; max-width: 92%; }
  .toast { font-size: 10px; padding: 6px 11px; }

  .dock { padding: 5px 8px calc(7px + env(safe-area-inset-bottom)); }
  .dock-inner { gap: 6px; }
  .tcard { width: 74px; padding: 5px 4px 5px; border-radius: 10px; }
  .ticon { width: 33px; height: 33px; }
  .tname { font-size: 7.5px; letter-spacing: 0.1em; }
  .tcost { font-size: 9px; }
  .tkey { width: 11px; height: 11px; font-size: 6px; top: 3px; left: 4px; }

  .overlay { padding: 14px; }
  .title-card { padding: 10px; }
  .title-card h1 { font-size: clamp(52px, 17vw, 84px); }
  .tagline { font-size: 12px; margin: 16px auto 14px; }
  .title-badges { gap: 18px; }
  .primary, .ghost { padding: 13px 22px; font-size: 10px; }
  .modal { padding: 22px 18px; border-radius: 16px; }
  .end-stats b { font-size: 14px; }
  .end-stats span { font-size: 6px; }
  .help-step { padding: 9px 10px; }
  .help-keys { gap: 5px 10px; }
}

@media (max-width: 380px) {
  .stat-ico { display: none; }
  .stat { padding: 4px 7px; }
  .tcard { width: 68px; }
  .ticon { width: 30px; height: 30px; }
  .wave-btn { width: 78px; height: 78px; }
  .wave-title { font-size: 6.8px; }
}

@media (max-height: 660px) and (min-width: 761px) {
  .hud { padding-top: 5px; padding-bottom: 5px; }
  .dock { padding-top: 4px; padding-bottom: 5px; }
  .tcard { width: 92px; }
  .ticon { width: 36px; height: 36px; }
  .title-card h1 { font-size: clamp(48px, 10vw, 86px); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

