645: // ---- simulation ----
646: 
647: let last = performance.now();
648: 
649: function loop(now) {
650:   const raw = Math.min((now - last) / 1000, 0.06);
651:   last = now;
652:   state.renderTime += raw;
653:   if (state.mode === 'playing') {
654:     let remain = raw * state.speed;
655:     let guard = 0;
656:     while (remain > 0.0001 && guard++ < 8) {
657:       const dt = Math.min(1 / 60, remain);
658:       simulate(dt);
659:       remain -= dt;
660:       if (state.mode !== 'playing') break;
661:     }
662:     updateUI();
663:   } else if (state.mode === 'menu') {
664:     updateAmbient(raw);
665:   }
666:   R.render(ctx, state);
667:   requestAnimationFrame(loop);
668: }
