725: function lerpAngle(a, b, t) {
726:   let d = ((b - a + Math.PI) % TAU + TAU) % TAU - Math.PI;
727:   return a + d * t;
728: }
729: 
730: function segmentHit(x1, y1, x2, y2, px, py, pad) {
731:   const dx = x2 - x1;
732:   const dy = y2 - y1;
733:   const len2 = dx * dx + dy * dy;
734:   if (len2 === 0) return Math.hypot(px - x1, py - y1) <= pad;
735:   let t = ((px - x1) * dx + (py - y1) * dy) / len2;
736:   t = Math.max(0, Math.min(1, t));
737:   return Math.hypot(px - (x1 + dx * t), py - (y1 + dy * t)) <= pad;
738: }
