758: function startWave(early) {
759:   if (state.mode !== 'playing' || state.waveActive) return;
760:   if (early && state.prep > 0) {
761:     const bonus = Math.ceil(state.prep) * 2;
762:     state.gold += bonus;
763:     state.stats.earned += bonus;
764:     toast(`Early call bonus +${bonus}g`, 'gold');
765:   }
766:   state.prep = 0;
767:   state.waveActive = true;
768:   state.waveTime = 0;
769:   state.waveSpawned = 0;
770:   const groups = C.waveGroups(state.wave);
771:   const queue = [];
772:   for (const grp of groups) {
773:     for (let i = 0; i < grp.count; i++) {
774:       queue.push({ type: grp.type, at: grp.start + i * grp.gap });
775:     }
776:   }
777:   queue.sort((a, b) => a.at - b.at);
778:   state.spawnQueue = queue;
779:   state.waveTotal = queue.length;
780:   sound.play('wave');
781:   banner(`WAVE ${state.wave}`);
782:   if (groups.some((grp) => grp.type === 'boss')) {
783:     toast('Leviathan signature detected', 'danger');
784:     sound.play('boss');
785:   }
786:   updateUI();
787: }
