807: function spawnEnemy(type) {
808:   const def = C.ENEMIES[type];
809:   if (!def) return;
810:   const mul = C.waveHpMul(state.wave);
811:   const hp = def.hp * mul;
812:   const start = C.PATH_POINTS[0];
813:   state.enemies.push({
814:     type,
815:     def,
816:     hp,
817:     maxHp: hp,
818:     speed: def.speed * (1 + Math.min(0.25, (state.wave - 1) * 0.006)),
819:     dist: 0,
820:     x: start.x,
821:     y: start.y,
822:     angle: 0,
823:     radius: def.radius,
824:     slowTimer: 0,
825:     slowAmount: 0,
826:     flash: 0,
827:     dead: false,
828:     seed: Math.random() * 100,
829:     reward: Math.round(def.reward * (1 + (state.wave - 1) * 0.02)),
830:   });
831:   state.portalPulse = 1;
832:   burst(C.PORTAL.x, C.PORTAL.y, type === 'boss' ? 18 : 6, def.color, type === 'boss' ? 120 : 55, 0.4);
833:   if (type === 'boss') {
834:     state.shake = Math.max(state.shake, 7);
835:     banner('LEVIATHAN');
836:   }
