839: // ---- combat ----
840: 
841: function findTarget(tower, range) {
842:   let best = null;
843:   for (const e of state.enemies) {
844:     if (e.dead) continue;
845:     const d = Math.hypot(e.x - tower.x, e.y - tower.y);
846:     if (d <= range + e.radius * 0.4) {
847:       if (!best || e.dist > best.dist) best = e;
848:     }
849:   }
850:   return best;
851: }
852: 
853: function damage(e, amount, opts = {}) {
854:   if (e.dead) return;
855:   const armor = e.def.armor || 0;
856:   const dealt = Math.max(1, amount * (1 - armor));
857:   e.hp -= dealt;
858:   e.flash = 1;
859:   state.stats.damage += dealt;
860:   if (opts.tower) opts.tower.damage += dealt;
861:   if (dealt >= 45 || opts.text) {
862:     addText(e.x, e.y - e.radius - 14, Math.round(dealt), opts.color || '#ffffff', dealt >= 100 ? 14 : 11);
863:   }
864:   if (e.hp <= 0) killEnemy(e, opts.tower);
865: }
866: 
867: function killEnemy(e, tower) {
868:   if (e.dead) return;
869:   e.dead = true;
870:   state.gold += e.reward;
871:   state.score += e.reward * 2;
872:   state.stats.kills++;
873:   state.stats.earned += e.reward;
874:   if (tower) tower.kills++;
875:   if (e.reward >= 18 || Math.random() < 0.22) {
876:     addText(e.x, e.y - e.radius - 4, `+${e.reward}`, '#ffd166', 11);
877:   }
878:   burst(e.x, e.y, e.type === 'boss' ? 34 : 12, e.def.color, e.type === 'boss' ? 200 : 100, 0.55);
879:   ring(e.x, e.y, e.type === 'boss' ? 80 : 24, e.def.color, 0.45);
880:   sound.play('kill');
881:   if (e.type === 'boss') {
882:     explosion(e.x, e.y, '#ff6b8b', 1.8);
883:     state.shake = 16;
884:     sound.play('boss');
885:   }
886: }
887: 
888: function leak(e) {
889:   if (state.mode !== 'playing') return;
890:   e.dead = true;
891:   const dmg = e.def.leak;
892:   state.lives -= dmg;
893:   state.stats.leaked++;
894:   state.flash = 1;
895:   state.shake = 14;
896:   state.corePulse = 1;
897:   addText(C.CORE.x - 10, C.CORE.y - 34, `-${dmg}`, '#ff5b6e', 18);
898:   sound.play('leak');
899:   if (state.lives <= 0) {
900:     state.lives = 0;
901:     endGame(false);
902:   }
903: }
904: 
905: function updateEnemies(dt) {
906:   for (const e of state.enemies) {
907:     if (e.dead) continue;
908:     if (e.slowTimer > 0) {
909:       e.slowTimer -= dt;
910:       if (e.slowTimer <= 0) e.slowAmount = 0;
911:     }
912:     const factor = e.slowTimer > 0 ? 1 - e.slowAmount : 1;
913:     e.dist += e.speed * factor * dt;
914:     const p = C.pathAt(e.dist);
915:     e.x = p.x;
916:     e.y = p.y;
917:     e.angle = p.angle;
918:     if (e.flash > 0) e.flash = Math.max(0, e.flash - dt * 5);
919:     if (e.type === 'boss' && Math.random() < dt * 14) {
920:       state.particles.push({
921:         x: e.x + (Math.random() - 0.5) * 20,
922:         y: e.y + (Math.random() - 0.5) * 20,
923:         vx: 0, vy: -14,
924:         life: 0.5, maxLife: 0.5,
925:         size: 2 + Math.random() * 2,
926:         color: '#ff6b8b', type: 'spark', drag: 1, gravity: 0,
927:       });
928:     }
929:     if (e.slowTimer > 0 && Math.random() < dt * 9) {
930:       state.particles.push({
931:         x: e.x + (Math.random() - 0.5) * e.radius * 2,
932:         y: e.y + (Math.random() - 0.5) * e.radius,
933:         vx: (Math.random() - 0.5) * 20,
934:         vy: -8 - Math.random() * 12,
935:         life: 0.45, maxLife: 0.45,
936:         size: 1.4 + Math.random() * 1.6,
937:         color: '#a9e6ff', type: 'spark', drag: 2, gravity: 0,
938:       });
939:     }
940:     if (e.dist >= C.PATH_LENGTH - 1) leak(e);
941:   }
942: }
