944: function fire(tower, def, lv, target) {
945:   const ox = tower.x;
946:   const oy = tower.y - 5;
947:   if (tower.type === 'pulse') {
948:     state.projectiles.push({
949:       kind: 'pulse', x: ox, y: oy, px: ox, py: oy,
950:       target, tx: target.x, ty: target.y,
951:       speed: 840, dmg: lv.dmg, color: def.color, tower, life: 2,
952:     });
953:     sound.play('shoot');
954:   } else if (tower.type === 'cannon') {
955:     const dist = Math.hypot(target.x - ox, target.y - oy);
956:     state.projectiles.push({
957:       kind: 'shell', sx: ox, sy: oy, x: ox, y: oy, px: ox, py: oy,
958:       tx: target.x, ty: target.y, t: 0, dur: Math.max(0.3, Math.min(0.95, dist / 540)),
959:       h: 46, dmg: lv.dmg, splash: lv.splash, color: def.color, tower,
960:     });
961:     sound.play('cannon');
962:   } else if (tower.type === 'cryo') {
963:     state.projectiles.push({
964:       kind: 'frost', x: ox, y: oy, px: ox, py: oy,
965:       target, tx: target.x, ty: target.y,
966:       speed: 660, dmg: lv.dmg, splash: lv.splash,
967:       slow: lv.slow, slowDur: lv.slowDur, color: def.color, tower, life: 2.2,
968:     });
969:     sound.play('frost');
970:   } else if (tower.type === 'arc') {
971:     const hit = [target];
972:     let cur = target;
973:     for (let i = 1; i < lv.chains; i++) {
974:       let next = null;
975:       let bestD = Infinity;
976:       for (const e of state.enemies) {
977:         if (e.dead || hit.includes(e)) continue;
978:         const d = Math.hypot(e.x - cur.x, e.y - cur.y);
979:         if (d < lv.chainRange && d < bestD) { bestD = d; next = e; }
980:       }
981:       if (!next) break;
982:       hit.push(next);
983:       cur = next;
984:     }
985:     const points = [{ x: ox, y: oy }];
986:     let dmg = lv.dmg;
987:     hit.forEach((e, i) => {
988:       points.push({ x: e.x, y: e.y });
989:       damage(e, dmg, { tower, text: i === 0, color: '#dcd2ff' });
990:       dmg *= 0.85;
991:     });
992:     state.beams.push({ points, life: 0.24, maxLife: 0.24, color: '#b9a6ff', width: 1.7 });
993:     sound.play('arc');
994:     tower.flash = 1;
995:   } else if (tower.type === 'rail') {
996:     const end = {
997:       x: ox + Math.cos(tower.angle) * lv.range,
998:       y: oy + Math.sin(tower.angle) * lv.range,
999:     };
1000:     for (const e of state.enemies) {
1001:       if (e.dead) continue;
1002:       if (segmentHit(ox, oy, end.x, end.y, e.x, e.y, e.radius + 7)) {
1003:         damage(e, lv.dmg, { tower, text: true, color: '#ffd2ec' });
1004:       }
1005:     }
1006:     state.beams.push({
1007:       points: [{ x: ox, y: oy }, end],
1008:       life: 0.32, maxLife: 0.32, color: '#ff8ad4', width: 3.4,
1009:     });
1010:     state.shake = Math.max(state.shake, 3);
1011:     sound.play('rail');
1012:     tower.flash = 1;
1013:   }
1014: }
1015: 
1016: function updateTowers(dt) {
1017:   for (const tower of state.towers) {
1018:     const def = C.TOWERS[tower.type];
1019:     const lv = def.levels[tower.level];
1020:     if (tower.flash > 0) tower.flash = Math.max(0, tower.flash - dt * 8);
1021:     if (tower.cooldown > 0) tower.cooldown -= dt;
1022:     if (!state.waveActive) {
1023:       tower.angle = -Math.PI / 2 + Math.sin(state.renderTime * 0.6 + tower.seed) * 0.5;
1024:       continue;
1025:     }
1026:     const target = findTarget(tower, lv.range);
1027:     if (target) {
1028:       const desired = Math.atan2(target.y - (tower.y - 5), target.x - tower.x);
1029:       tower.angle = lerpAngle(tower.angle, desired, Math.min(1, dt * 14));
1030:       if (tower.cooldown <= 0) {
1031:         fire(tower, def, lv, target);
1032:         tower.cooldown = 1 / lv.rate;
1033:       }
1034:     }
1035:   }
1036: }
1037: 
1038: function updateProjectiles(dt) {
1039:   for (const p of state.projectiles) {
1040:     if (p.dead) continue;
1041:     p.px = p.x;
1042:     p.py = p.y;
1043:     if (p.kind === 'pulse') {
1044:       if (p.target && !p.target.dead) {
1045:         p.tx = p.target.x;
